\copy (WITH history_vehicles AS (SELECT DISTINCT vch.tenant_id, vch.vehicle_id FROM vehicle_cluster_history vch JOIN tenant_details td ON td.tenant_id = vch.tenant_id WHERE vch.week_start = '2026-11-02' AND td.tenant_drp = 2 AND (td.config->'VEHICLE_DRIVER_HISTORY'->>'enabled')::boolean IS TRUE), vehicle_cluster_counts AS (SELECT vch.tenant_id, vch.vehicle_id, kv.key::bigint AS cluster_id FROM vehicle_cluster_history vch JOIN history_vehicles hv ON hv.tenant_id = vch.tenant_id AND hv.vehicle_id = vch.vehicle_id CROSS JOIN LATERAL jsonb_each_text(vch.cluster_counts) AS kv(key, value) WHERE vch.week_start = '2026-11-02') SELECT DISTINCT vcc.tenant_id, vcc.vehicle_id FROM vehicle_cluster_counts vcc JOIN cluster_details cd ON cd.cluster_id = vcc.cluster_id WHERE cd.driver_id > 0) TO '/Users/swapnilmane/NetraDyne/driver_history_use/data/AN-37740/step_1/an37740_drp2_vehicles_with_candidate.csv' WITH CSV HEADER;
